#!/bin/bash
# §44g step ablation of the F8K chain under the newest TRAIN-only heads, 150 seeded VT shots (paired): F8K vs dropping xhe / xp / jgn / kw
# (the first kappa warp; kw2 stays). Measures each step's net S (tri_bot loss slope 0.62 in the xhe chain vs 0.79 without; kw damages li on
# quench shots). Then stage_decomp per arm.
cd /home/mohhakami/Documents/paper/quworld; export CUDA_VISIBLE_DEVICES=0 PYTHONUNBUFFERED=1; LOG=runs/strat/fusion/s44g_step_ablation.log
env QW_GPU_GB=30 runs/capped.sh s44g 40 .venv/bin/python paper/strat/fusion/gpu_build.py --split vt --tag S44G --psi psiF --psis "PQmix~g" \
  --guard psiF:0.25 --qb qh50 --qbheads "head_qb_QH_s1+head_qb_QH_s2+head_qb_QH_s3+head_qb_QH_s4+head_qb_QH_s5+head_qb_QH_s6" --heads "head_boundary_v8_J1RL_s1*3+head_boundary_v8_J1QPIpi_s1+head_boundary_v8_J1QPIpi_s2+head_boundary_v8_J1QH_s1+head_boundary_v8_J1QH_s2+head_boundary_v8_J1QH_s3" --xpheads head_xp_XP1_s1+head_xp_XP1_s2+head_xp_XP1_s3 --kws '{"F8K": {"_steps": ["shift", "bw", "xhe", "kw", "xp", "jgn", "li", "li2", "kw2"], "xp": {"sigma": 0.15, "cap": 0.1}, "li": {"cap": 0.9}, "xhe": {"gate": 0.01}}, "no_xhe": {"_steps": ["shift", "bw", "kw", "xp", "jgn", "li", "li2", "kw2"], "xp": {"sigma": 0.15, "cap": 0.1}, "li": {"cap": 0.9}, "xhe": {"gate": 0.01}}, "no_xp": {"_steps": ["shift", "bw", "xhe", "kw", "jgn", "li", "li2", "kw2"], "xp": {"sigma": 0.15, "cap": 0.1}, "li": {"cap": 0.9}, "xhe": {"gate": 0.01}}, "no_jgn": {"_steps": ["shift", "bw", "xhe", "kw", "xp", "li", "li2", "kw2"], "xp": {"sigma": 0.15, "cap": 0.1}, "li": {"cap": 0.9}, "xhe": {"gate": 0.01}}, "no_kw": {"_steps": ["shift", "bw", "xhe", "xp", "jgn", "li", "li2", "kw2"], "xp": {"sigma": 0.15, "cap": 0.1}, "li": {"cap": 0.9}, "xhe": {"gate": 0.01}}}' --axis head \
  --qbclamp --vt-shots "45,54,56,67,76,157,258,317,343,388,554,610,667,698,739,753,765,813,902,931,964,975,1001,1026,1152,1153,1198,1208,1223,1389,1407,1436,1489,1531,1568,1572,1577,1626,1628,1698,1959,1991,2052,2097,2237,2256,2288,2359,2444,2452,2534,2564,2581,2596,2608,2616,2674,2686,2703,2716,2765,2796,2939,2960,2986,2987,3012,3026,3028,3073,3124,3205,3206,3225,3365,3378,3420,3468,3470,3643,3644,3661,3769,3796,3797,3805,3843,3863,3881,3901,4018,4047,4119,4154,4160,4188,4270,4278,4316,4340,4490,4542,4566,4636,4646,4669,4706,4736,4767,4798,4845,4867,5023,5062,5131,5140,5259,5310,5390,5491,5668,5687,5734,5833,5897,5899,5938,6003,6081,6118,6174,6199,6218,6253,6287,6312,6314,6530,6566,6609,6615,6682,6686,6787,6791,6822,6872,6935,6983,7005" >> $LOG 2>&1 || { echo "CRASH s44g vt $(date -Is)" >> $LOG; exit 1; }
